import { sql } from 'drizzle-orm';
import {
  boolean,
  check,
  customType,
  date,
  foreignKey,
  index,
  integer,
  jsonb,
  numeric,
  pgEnum,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  type AnyPgColumn,
} from 'drizzle-orm/pg-core';

// IDs are UUIDv7 (time-ordered), generated by the API so keyset pagination
// on id follows creation order.

const createdAt = () =>
  timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true }).notNull().defaultNow();

export const ROLES = [
  'learner',
  'admin',
  'content_editor',
  'legal_reviewer',
  'publisher',
  'analyst',
] as const;
export type Role = (typeof ROLES)[number];

export const users = pgTable('users', {
  id: uuid('id').primaryKey(),
  email: text('email').notNull().unique(), // stored lower-cased
  displayName: text('display_name').notNull(),
  passwordHash: text('password_hash').notNull(),
  roles: text('roles').array().$type<Role[]>().notNull(),
  isActive: boolean('is_active').notNull().default(true),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/** Opaque refresh tokens; only a SHA-256 hash is stored. Rotated on use. */
export const refreshTokens = pgTable(
  'refresh_tokens',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    tokenHash: text('token_hash').notNull().unique(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index('refresh_tokens_user_idx').on(t.userId)],
);

/** Every role except learner: the accounts admins manage on the Staff page. */
export const STAFF_ROLES = ROLES.filter(
  (r): r is Exclude<Role, 'learner'> => r !== 'learner',
);

/**
 * One-time links for a staff member to choose their password: made when an
 * admin invites them or resets their access. Only a SHA-256 hash is stored;
 * a link works once, until it expires, and a newer link replaces it.
 */
export const staffSetupTokens = pgTable(
  'staff_setup_tokens',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    tokenHash: text('token_hash').notNull().unique(),
    createdBy: uuid('created_by')
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    usedAt: timestamp('used_at', { withTimezone: true }),
  },
  (t) => [index('staff_setup_tokens_user_idx').on(t.userId)],
);

/**
 * The emailed code for a learner who forgot their password. One per account:
 * a new request replaces it. Only a SHA-256 hash is stored; it works until it
 * expires or after too many wrong tries.
 */
export const passwordResetCodes = pgTable('password_reset_codes', {
  userId: uuid('user_id')
    .primaryKey()
    .references(() => users.id, { onDelete: 'cascade' }),
  codeHash: text('code_hash').notNull(),
  /** Tries used so far, taken before each guess is checked (so a right guess counts too). */
  wrongTries: integer('wrong_tries').notNull().default(0),
  expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  createdAt: createdAt(),
});

// ---------------------------------------------------------------- taxonomy

export const subjects = pgTable('subjects', {
  id: uuid('id').primaryKey(),
  slug: text('slug').notNull().unique(),
  name: text('name').notNull(),
  description: text('description'),
  sortOrder: integer('sort_order').notNull().default(0),
  isActive: boolean('is_active').notNull().default(true),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const acts = pgTable('acts', {
  id: uuid('id').primaryKey(),
  slug: text('slug').notNull().unique(),
  name: text('name').notNull(),
  shortName: text('short_name'),
  year: smallint('year'),
  jurisdiction: text('jurisdiction').notNull().default('IN'),
  isActive: boolean('is_active').notNull().default(true),
  /** The day the Act stopped applying (e.g. a code replaced by a newer one). */
  repealedOn: date('repealed_on'),
  replacedByActId: uuid('replaced_by_act_id').references(
    (): AnyPgColumn => acts.id,
  ),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const topics = pgTable(
  'topics',
  {
    id: uuid('id').primaryKey(),
    subjectId: uuid('subject_id')
      .notNull()
      .references(() => subjects.id),
    actId: uuid('act_id').references(() => acts.id),
    slug: text('slug').notNull().unique(),
    name: text('name').notNull(),
    description: text('description'),
    sortOrder: integer('sort_order').notNull().default(0),
    isActive: boolean('is_active').notNull().default(true),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index('topics_subject_idx').on(t.subjectId)],
);

// ---------------------------------------------------------------- provenance

export const CONTENT_SOURCE_KINDS = [
  'official_bci',
  'third_party',
  'original',
] as const;
export type ContentSourceKind = (typeof CONTENT_SOURCE_KINDS)[number];
export const contentSourceKind = pgEnum(
  'content_source_kind',
  CONTENT_SOURCE_KINDS,
);

/**
 * Historical licence record. The application no longer reads, shows or
 * changes it and nothing is gated on it; the column and its values are kept
 * only so existing records are preserved.
 */
export const LICENSE_STATUSES = [
  'pending',
  'permission_granted',
  'permitted_by_terms',
  'blocked',
] as const;
export type LicenseStatus = (typeof LICENSE_STATUSES)[number];
export const licenseStatus = pgEnum('license_status', LICENSE_STATUSES);

/**
 * Which law a question is about: the codes in force before 1 July 2024 (IPC,
 * CrPC, Evidence Act), the newer ones (BNS, BNSS, BSA), both, or neither. It
 * is a label only; the question's wording is never changed.
 */
export const LAW_REGIMES = [
  'old_codes',
  'new_codes',
  'both',
  'neutral',
] as const;
export type LawRegime = (typeof LAW_REGIMES)[number];
export const lawRegime = pgEnum('law_regime', LAW_REGIMES);

/**
 * A document or publisher that content came from: attribution and provenance
 * only. It never blocks importing or publishing. The license_* columns are a
 * preserved historical record that the application no longer uses. Content
 * written in-house has no source row.
 */
export const contentSources = pgTable(
  'content_sources',
  {
    id: uuid('id').primaryKey(),
    kind: contentSourceKind('kind').notNull(),
    title: text('title').notNull(),
    publisher: text('publisher'),
    url: text('url'),
    retrievedOn: date('retrieved_on'),
    /** SHA-256 of the source document, as lower-case hex. */
    sha256: text('sha256'),
    licenseStatus: licenseStatus('license_status').notNull().default('pending'),
    licenseNote: text('license_note'),
    allowedUses: text('allowed_uses')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    createdBy: uuid('created_by').references(() => users.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('content_sources_license_idx').on(t.licenseStatus),
    check(
      'content_sources_url_https',
      sql`${t.url} is null or ${t.url} ~ '^https://'`,
    ),
    check(
      'content_sources_sha256_hex',
      sql`${t.sha256} is null or ${t.sha256} ~ '^[0-9a-f]{64}$'`,
    ),
  ],
);

// ---------------------------------------------------------------- questions

export const VERSION_STATUSES = [
  'draft',
  'in_review',
  'changes_requested',
  'approved',
  'published',
  'superseded',
  'retired',
] as const;
export type VersionStatus = (typeof VERSION_STATUSES)[number];
export const versionStatus = pgEnum(
  'question_version_status',
  VERSION_STATUSES,
);

export const QUESTION_TYPES = ['single_select'] as const;
export type QuestionType = (typeof QUESTION_TYPES)[number];
export const questionType = pgEnum('question_type', QUESTION_TYPES);

export interface QuestionOption {
  id: string;
  text: string;
}

/** Stable identity of a question across all its versions. */
export const questions = pgTable('questions', {
  id: uuid('id').primaryKey(),
  /** Id in an outside source (e.g. the app's bundled bank), for idempotent imports. */
  externalRef: text('external_ref').unique(),
  liveVersionId: uuid('live_version_id').references(
    (): AnyPgColumn => questionVersions.id,
  ),
  createdBy: uuid('created_by').references(() => users.id),
  retiredAt: timestamp('retired_at', { withTimezone: true }),
  /**
   * True for questions meant only for the mock exams. Every game mode skips
   * them. An ordinary question stays false and is shared with an exam by
   * tagging it (exam_question_tags).
   */
  examOnly: boolean('exam_only').notNull().default(false),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/**
 * One revision of a question. Only the latest version of a question can
 * change, and only while it is a draft or has changes requested; a published
 * version is immutable and a correction is a new version.
 */
export const questionVersions = pgTable(
  'question_versions',
  {
    id: uuid('id').primaryKey(),
    questionId: uuid('question_id')
      .notNull()
      .references(() => questions.id),
    versionNo: integer('version_no').notNull(),
    status: versionStatus('status').notNull().default('draft'),
    topicId: uuid('topic_id')
      .notNull()
      .references(() => topics.id),
    jurisdiction: text('jurisdiction').notNull().default('IN'),
    language: text('language').notNull().default('en'),
    questionType: questionType('question_type')
      .notNull()
      .default('single_select'),
    difficulty: smallint('difficulty').notNull().default(1),
    stem: text('stem').notNull().default(''),
    options: jsonb('options').$type<QuestionOption[]>().notNull().default([]),
    correctOptionIds: text('correct_option_ids')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    explanation: text('explanation').notNull().default(''),
    sourceTitle: text('source_title'),
    sourceUrl: text('source_url'),
    citation: text('citation'),
    provisionReference: text('provision_reference'),
    validFrom: date('valid_from'),
    validTo: date('valid_to'),
    /**
     * Further options an official key also accepts (any one of them counts).
     * Never overlaps correct_option_ids; each must be one of the options.
     */
    alternateCorrectOptionIds: text('alternate_correct_option_ids')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    /** Exams show the options in their stored order (e.g. "Both A and B"). */
    lockOptionOrder: boolean('lock_option_order').notNull().default(false),
    lawRegime: lawRegime('law_regime').notNull().default('neutral'),
    /** A reviewer's note on the law's current state; never part of the question. */
    currencyNote: text('currency_note'),
    /** Where the content came from (attribution only). */
    contentSourceId: uuid('content_source_id').references(
      () => contentSources.id,
    ),
    /** Optional key to keep near-duplicate questions out of one mock. */
    conceptKey: text('concept_key'),
    verifiedAt: timestamp('verified_at', { withTimezone: true }),
    reviewerId: uuid('reviewer_id').references(() => users.id),
    changeNote: text('change_note'),
    createdBy: uuid('created_by').references(() => users.id),
    updatedBy: uuid('updated_by').references(() => users.id),
    submittedAt: timestamp('submitted_at', { withTimezone: true }),
    approvedAt: timestamp('approved_at', { withTimezone: true }),
    publishedAt: timestamp('published_at', { withTimezone: true }),
    publishedBy: uuid('published_by').references(() => users.id),
    endedAt: timestamp('ended_at', { withTimezone: true }), // superseded or retired
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex('question_versions_question_no_idx').on(
      t.questionId,
      t.versionNo,
    ),
    index('question_versions_status_idx').on(t.status),
    index('question_versions_topic_idx').on(t.topicId),
    index('question_versions_content_source_idx').on(t.contentSourceId),
    check('difficulty_range', sql`${t.difficulty} between 1 and 3`),
    check(
      'alternate_disjoint_from_correct',
      sql`not (${t.alternateCorrectOptionIds} && ${t.correctOptionIds})`,
    ),
  ],
);

/** The Acts a question version is about (for old/new code labels and search). */
export const questionVersionActs = pgTable(
  'question_version_acts',
  {
    versionId: uuid('version_id')
      .notNull()
      .references(() => questionVersions.id),
    actId: uuid('act_id')
      .notNull()
      .references(() => acts.id),
  },
  (t) => [
    primaryKey({ columns: [t.versionId, t.actId] }),
    index('question_version_acts_act_idx').on(t.actId),
  ],
);

export const REVIEW_DECISIONS = ['approved', 'changes_requested'] as const;
export const reviewDecision = pgEnum('review_decision', REVIEW_DECISIONS);

export const reviewDecisions = pgTable(
  'review_decisions',
  {
    id: uuid('id').primaryKey(),
    versionId: uuid('version_id')
      .notNull()
      .references(() => questionVersions.id),
    reviewerId: uuid('reviewer_id')
      .notNull()
      .references(() => users.id),
    decision: reviewDecision('decision').notNull(),
    reason: text('reason'),
    createdAt: createdAt(),
  },
  (t) => [index('review_decisions_version_idx').on(t.versionId)],
);

/** Append-only record of sensitive actions. Never updated or deleted. */
export const auditLog = pgTable(
  'audit_log',
  {
    id: uuid('id').primaryKey(),
    actorId: uuid('actor_id').references(() => users.id),
    action: text('action').notNull(),
    entityType: text('entity_type').notNull(),
    entityId: uuid('entity_id'),
    data: jsonb('data').$type<Record<string, unknown>>(),
    requestId: text('request_id'),
    createdAt: createdAt(),
  },
  (t) => [index('audit_log_entity_idx').on(t.entityType, t.entityId)],
);

/**
 * Attempt counters shared by every API copy (sign-in limits). The key is a
 * hash, so no email or address is stored. A counter starts again at
 * reset_at; old rows are swept now and then.
 */
export const rateLimits = pgTable(
  'rate_limits',
  {
    key: text('key').primaryKey(),
    hits: integer('hits').notNull(),
    resetAt: timestamp('reset_at', { withTimezone: true }).notNull(),
  },
  (t) => [index('rate_limits_reset_at_idx').on(t.resetAt)],
);

// ---------------------------------------------------------------- learning

/**
 * immediate: each answer is final and its explanation is returned at once
 * (practice). end: answers can change until submit and nothing is revealed
 * before it (exam). Follows from the session's mode, so it is not stored.
 */
export const FEEDBACK_MODES = ['immediate', 'end'] as const;
export type FeedbackMode = (typeof FEEDBACK_MODES)[number];

/** The app's four ways to play; decides feedback, rewards and the daily set. */
export const QUIZ_MODES = [
  'case_path',
  'daily_docket',
  'duel',
  'exam',
  'mistake_review',
] as const;
export type QuizMode = (typeof QUIZ_MODES)[number];
export const quizMode = pgEnum('quiz_mode', QUIZ_MODES);

/**
 * One attempt at a quiz. The server picks the questions and owns the result.
 * In progress until submitted_at is set. Feedback, the daily set's date, the
 * deadline and the score are worked out from these columns, not stored.
 */
export const quizSessions = pgTable(
  'quiz_sessions',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id),
    mode: quizMode('mode').notNull(),
    language: text('language').notNull(),
    /** One difficulty is stored as min = max; null means any. */
    minDifficulty: smallint('min_difficulty'),
    maxDifficulty: smallint('max_difficulty'),
    scoringVersion: text('scoring_version').notNull(),
    questionCount: integer('question_count').notNull(),
    startedAt: timestamp('started_at', { withTimezone: true }).notNull(),
    submittedAt: timestamp('submitted_at', { withTimezone: true }),
    correctCount: integer('correct_count'),
    answeredCount: integer('answered_count'),
    /** XP given at submit; depends on the streak and best stars at that time. */
    xpAwarded: integer('xp_awarded'),
  },
  (t) => [index('quiz_sessions_user_idx').on(t.userId, t.id)],
);

/** Topics a session's questions were drawn from; none means every topic. */
export const quizSessionTopics = pgTable(
  'quiz_session_topics',
  {
    sessionId: uuid('session_id')
      .notNull()
      .references(() => quizSessions.id, { onDelete: 'cascade' }),
    topicId: uuid('topic_id')
      .notNull()
      .references(() => topics.id),
  },
  (t) => [primaryKey({ columns: [t.sessionId, t.topicId] })],
);

/**
 * The exact question versions a session showed, in order. Versions are
 * immutable, so results stay reproducible after a question is revised.
 */
export const quizSessionQuestions = pgTable(
  'quiz_session_questions',
  {
    sessionId: uuid('session_id')
      .notNull()
      .references(() => quizSessions.id, { onDelete: 'cascade' }),
    position: smallint('position').notNull(),
    questionVersionId: uuid('question_version_id')
      .notNull()
      .references(() => questionVersions.id),
    /** Option ids in the order this learner sees them. */
    optionOrder: text('option_order').array().notNull(),
    selectedOptionIds: text('selected_option_ids').array(),
    answeredAt: timestamp('answered_at', { withTimezone: true }),
    isCorrect: boolean('is_correct'),
    /** Time the app measured from showing the question to the answer (duels race on it). */
    elapsedMs: integer('elapsed_ms'),
  },
  (t) => [
    primaryKey({ columns: [t.sessionId, t.position] }),
    uniqueIndex('quiz_session_questions_version_idx').on(
      t.sessionId,
      t.questionVersionId,
    ),
  ],
);

export const DUEL_OUTCOMES = ['won', 'lost', 'draw'] as const;
export const duelOutcome = pgEnum('duel_outcome', DUEL_OUTCOMES);

/**
 * The opponent of a duel session and how it ended. The opponent is another
 * learner's finished duel on the same questions (opponent_session_id), or a
 * practice player when none fitted. Their answers are copied in, so the
 * result stays the same whatever happens to their account. Outcome and the
 * rating after are set on submit; a learner's rating is their latest.
 */
export const duelMatches = pgTable(
  'duel_matches',
  {
    sessionId: uuid('session_id')
      .primaryKey()
      .references(() => quizSessions.id, { onDelete: 'cascade' }),
    opponentSessionId: uuid('opponent_session_id').references(
      (): AnyPgColumn => quizSessions.id,
      { onDelete: 'set null' },
    ),
    /** "Asha K." (league rule), or the practice player's name. */
    opponentName: text('opponent_name').notNull(),
    practice: boolean('practice').notNull(),
    opponentRating: integer('opponent_rating').notNull(),
    opponentAnswers: jsonb('opponent_answers')
      .$type<{ correct: boolean; elapsed_ms: number }[]>()
      .notNull(),
    ratingBefore: integer('rating_before').notNull(),
    playerPoints: integer('player_points'),
    opponentPoints: integer('opponent_points'),
    outcome: duelOutcome('outcome'),
    ratingAfter: integer('rating_after'),
  },
  (t) => [index('duel_matches_opponent_idx').on(t.opponentSessionId)],
);

/** AI chat answers per learner per India date, for the daily limit. */
export const chatUsage = pgTable(
  'chat_usage',
  {
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    day: date('day').notNull(),
    answers: integer('answers').notNull().default(0),
  },
  (t) => [primaryKey({ columns: [t.userId, t.day] })],
);

/** Chapter chests a learner has opened on the Case Path road (one per subject). */
export const chestOpenings = pgTable(
  'chest_openings',
  {
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    subjectId: uuid('subject_id')
      .notNull()
      .references(() => subjects.id),
    openedAt: timestamp('opened_at', { withTimezone: true }).notNull(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.subjectId] })],
);

// ---------------------------------------------------------------- economy

/**
 * Why coins moved. Earning: welcome (once), new_stars, daily_docket,
 * daily_goal and streak_milestone (per quiz session), chest (per subject).
 * Spending: energy_refill, streak_freeze (the freeze purchase itself).
 * league_top3: finishing a week in the top 3 of a league group (per cohort).
 */
export const COIN_REASONS = [
  'welcome',
  'new_stars',
  'daily_docket',
  'daily_goal',
  'streak_milestone',
  'chest',
  'energy_refill',
  'streak_freeze',
  'league_top3',
  'duel_win',
] as const;
export type CoinReason = (typeof COIN_REASONS)[number];
export const coinReason = pgEnum('coin_reason', COIN_REASONS);

/**
 * Every coin earned (+) or spent (−). The balance is the sum, never stored.
 * A reward is paid once per session or chest (partial unique indexes).
 */
export const coinLedger = pgTable(
  'coin_ledger',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    amount: integer('amount').notNull(),
    reason: coinReason('reason').notNull(),
    sessionId: uuid('session_id').references(() => quizSessions.id, {
      onDelete: 'set null',
    }),
    subjectId: uuid('subject_id').references(() => subjects.id),
    /** league_top3: the league group the bonus is for. */
    cohortId: uuid('cohort_id').references((): AnyPgColumn => leagueCohorts.id),
    createdAt: createdAt(),
  },
  (t) => [
    index('coin_ledger_user_idx').on(t.userId),
    uniqueIndex('coin_ledger_cohort_idx')
      .on(t.userId, t.cohortId)
      .where(sql`${t.cohortId} is not null`),
    uniqueIndex('coin_ledger_session_reason_idx')
      .on(t.userId, t.reason, t.sessionId)
      .where(sql`${t.sessionId} is not null`),
    uniqueIndex('coin_ledger_chest_idx')
      .on(t.userId, t.subjectId)
      .where(sql`${t.reason} = 'chest'`),
    uniqueIndex('coin_ledger_welcome_idx')
      .on(t.userId)
      .where(sql`${t.reason} = 'welcome'`),
  ],
);

/** quiz_start (−cost), quiz_refund (quit before answering), three_star_bonus, refill. */
export const ENERGY_REASONS = [
  'quiz_start',
  'quiz_refund',
  'three_star_bonus',
  'refill',
] as const;
export type EnergyReason = (typeof ENERGY_REASONS)[number];
export const energyReason = pgEnum('energy_reason', ENERGY_REASONS);

/**
 * Energy used and gained. Today's energy is the free daily amount plus the
 * rows dated today (India), so nothing has to be reset at midnight.
 */
export const energyLedger = pgTable(
  'energy_ledger',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    amount: integer('amount').notNull(),
    reason: energyReason('reason').notNull(),
    sessionId: uuid('session_id').references(() => quizSessions.id, {
      onDelete: 'set null',
    }),
    createdAt: createdAt(),
  },
  (t) => [
    index('energy_ledger_user_idx').on(t.userId, t.createdAt),
    uniqueIndex('energy_ledger_session_reason_idx')
      .on(t.sessionId, t.reason)
      .where(sql`${t.sessionId} is not null`),
  ],
);

export const PERSONAS = ['advocate', 'aspirant', 'citizen'] as const;
export const persona = pgEnum('persona', PERSONAS);

/**
 * Learning settings that follow the account (the name is users.display_name).
 * Theme, sound, haptics and reminders stay on each phone.
 */
export const learnerSettings = pgTable('learner_settings', {
  userId: uuid('user_id')
    .primaryKey()
    .references(() => users.id, { onDelete: 'cascade' }),
  persona: persona('persona').notNull(),
  language: text('language').notNull(),
  dailyGoal: smallint('daily_goal').notNull(),
  onboardedAt: timestamp('onboarded_at', { withTimezone: true }),
  updatedAt: updatedAt(),
});

/**
 * Premium learners. A row means premium. Until real store purchases exist the
 * app turns it on itself (source 'demo', testing only).
 */
export const premiumMemberships = pgTable('premium_memberships', {
  userId: uuid('user_id')
    .primaryKey()
    .references(() => users.id, { onDelete: 'cascade' }),
  source: text('source').notNull(),
  startedAt: timestamp('started_at', { withTimezone: true }).notNull(),
});

// ---------------------------------------------------------------- leagues

/**
 * One weekly league group of up to 30 learners at one tier. Weeks are ISO
 * weeks in India time (`2026-W44`). Standings, results and tier changes are
 * worked out from the members' quiz XP, not stored.
 */
export const leagueCohorts = pgTable(
  'league_cohorts',
  {
    id: uuid('id').primaryKey(),
    weekId: text('week_id').notNull(),
    tier: smallint('tier').notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    index('league_cohorts_week_tier_idx').on(t.weekId, t.tier),
    // Lets memberships check that their week matches their group's week.
    uniqueIndex('league_cohorts_id_week_idx').on(t.id, t.weekId),
  ],
);

/** A learner's group for one week; one group per learner per week. */
export const leagueMemberships = pgTable(
  'league_memberships',
  {
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    weekId: text('week_id').notNull(),
    cohortId: uuid('cohort_id').notNull(),
    joinedAt: timestamp('joined_at', { withTimezone: true }).notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.userId, t.weekId] }),
    index('league_memberships_cohort_idx').on(t.cohortId),
    foreignKey({
      columns: [t.cohortId, t.weekId],
      foreignColumns: [leagueCohorts.id, leagueCohorts.weekId],
    }).onDelete('cascade'),
  ],
);

// ---------------------------------------------------------------- legal news

export const NEWS_CATEGORIES = [
  'supreme_court',
  'high_courts',
  'legislation',
  'explainer',
] as const;
export type NewsCategory = (typeof NEWS_CATEGORIES)[number];
export const newsCategory = pgEnum('news_category', NEWS_CATEGORIES);

export const NEWS_STATUSES = [
  'draft',
  'in_review',
  'changes_requested',
  'approved',
  'published',
  'retired',
] as const;
export type NewsStatus = (typeof NEWS_STATUSES)[number];
export const newsStatus = pgEnum('news_status', NEWS_STATUSES);

/**
 * A legal news article for the app's Updates tab, in English. It goes through
 * the same steps as a question (an editor writes, a legal reviewer approves,
 * a publisher publishes) but keeps one row: correcting a published article
 * takes it back to draft, off the app, until it is approved again. Review
 * decisions and their reasons are in the audit log.
 */
export const newsArticles = pgTable(
  'news_articles',
  {
    id: uuid('id').primaryKey(),
    /** Id in an outside source (the app's starter articles). */
    externalRef: text('external_ref').unique(),
    status: newsStatus('status').notNull().default('draft'),
    category: newsCategory('category').notNull(),
    title: text('title').notNull().default(''),
    summary: text('summary').notNull().default(''),
    keyPoints: text('key_points')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    whyItMatters: text('why_it_matters').notNull().default(''),
    /** Who decided or passed it and when, e.g. "Supreme Court of India, 8 April 2025". */
    source: text('source').notNull().default(''),
    sourceUrl: text('source_url'),
    /** The day of the judgment, Act or event. */
    eventDate: date('event_date'),
    readMinutes: smallint('read_minutes').notNull().default(3),
    createdBy: uuid('created_by').references(() => users.id),
    updatedBy: uuid('updated_by').references(() => users.id),
    reviewerId: uuid('reviewer_id').references(() => users.id),
    approvedAt: timestamp('approved_at', { withTimezone: true }),
    publishedBy: uuid('published_by').references(() => users.id),
    publishedAt: timestamp('published_at', { withTimezone: true }),
    retiredAt: timestamp('retired_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('news_articles_status_idx').on(t.status, t.eventDate),
    check('read_minutes_range', sql`${t.readMinutes} between 1 and 30`),
  ],
);

/** Raw bytes (Postgres bytea), read and written as a Node Buffer. */
const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType: () => 'bytea',
});

/**
 * The picture shown on a news article's card in the app, uploaded in the
 * portal. Kept here (not in a file store) so it is in the database backups.
 * The API re-encodes every upload as WebP, so only safe, small images are
 * stored. [version] changes with the bytes and goes into the picture's
 * address, so the app can cache it for good.
 */
export const newsImages = pgTable('news_images', {
  articleId: uuid('article_id')
    .primaryKey()
    .references(() => newsArticles.id, { onDelete: 'cascade' }),
  data: bytea('data').notNull(),
  width: integer('width').notNull(),
  height: integer('height').notNull(),
  version: text('version').notNull(),
  uploadedBy: uuid('uploaded_by').references(() => users.id),
  createdAt: createdAt(),
});

// ---------------------------------------------------------------- daily tips

export const DAILY_TIP_CATEGORIES = [
  'citizen_rights',
  'criminal_law',
  'consumer_rights',
  'family_law',
  'property',
  'workplace',
  'general',
] as const;
export type DailyTipCategory = (typeof DAILY_TIP_CATEGORIES)[number];
export const dailyTipCategory = pgEnum(
  'daily_tip_category',
  DAILY_TIP_CATEGORIES,
);

export const DAILY_TIP_STATUSES = [
  'draft',
  'in_review',
  'changes_requested',
  'approved',
  'published',
  'retired',
] as const;
export type DailyTipStatus = (typeof DAILY_TIP_STATUSES)[number];
export const dailyTipStatus = pgEnum('daily_tip_status', DAILY_TIP_STATUSES);

/** Languages a tip can be written in (the app's six). */
export const DAILY_TIP_LANGUAGES = [
  'en',
  'hi',
  'ta',
  'te',
  'kn',
  'ml',
] as const;

/**
 * A short legal tip for the app's Home screen. It follows the news article's
 * lifecycle (an editor writes, a legal reviewer approves, a publisher
 * publishes) and keeps one row: correcting a published tip takes it back to
 * draft until it is approved again. The app shows the published tip whose
 * [publishDate] is today (India), so scheduling is a query, not a job. Review
 * decisions and their reasons are in the audit log.
 */
export const dailyTips = pgTable(
  'daily_tips',
  {
    id: uuid('id').primaryKey(),
    status: dailyTipStatus('status').notNull().default('draft'),
    category: dailyTipCategory('category').notNull(),
    language: text('language').notNull().default('en'),
    title: text('title').notNull().default(''),
    summary: text('summary').notNull().default(''),
    explanation: text('explanation').notNull().default(''),
    /** The Act and section, e.g. "Consumer Protection Act, 2019, Section 35". */
    legalReference: text('legal_reference').notNull().default(''),
    sourceUrl: text('source_url'),
    /** The India day the tip is shown on the app's Home screen. */
    publishDate: date('publish_date'),
    /** When an editor last checked the tip against its official source. */
    lastVerifiedOn: date('last_verified_on'),
    createdBy: uuid('created_by').references(() => users.id),
    updatedBy: uuid('updated_by').references(() => users.id),
    reviewerId: uuid('reviewer_id').references(() => users.id),
    approvedAt: timestamp('approved_at', { withTimezone: true }),
    publishedBy: uuid('published_by').references(() => users.id),
    publishedAt: timestamp('published_at', { withTimezone: true }),
    retiredAt: timestamp('retired_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('daily_tips_status_idx').on(t.status, t.publishDate),
    // One live tip per day and language.
    uniqueIndex('daily_tips_live_day_idx')
      .on(t.publishDate, t.language)
      .where(sql`${t.status} = 'published'`),
  ],
);

// ---------------------------------------------------------------- review & reports

/**
 * Questions a learner saved. Points at the question, not a version, so a
 * saved question shows its latest version and survives revisions.
 */
export const questionBookmarks = pgTable(
  'question_bookmarks',
  {
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    questionId: uuid('question_id')
      .notNull()
      .references(() => questions.id),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.questionId] })],
);

export const REPORT_REASONS = [
  'wrong_answer',
  'unclear',
  'outdated_law',
  'typo',
  'other',
] as const;
export type ReportReason = (typeof REPORT_REASONS)[number];
export const reportReason = pgEnum('report_reason', REPORT_REASONS);

/** How staff closed a report: the question was fixed, retired, or needed no change. */
export const REPORT_OUTCOMES = ['fixed', 'retired', 'no_change'] as const;
export type ReportOutcome = (typeof REPORT_OUTCOMES)[number];
export const reportOutcome = pgEnum('report_outcome', REPORT_OUTCOMES);

/**
 * A learner's report about the exact question version they saw. Reports
 * never change content; staff fix or retire the question, then close the
 * report. Open = no outcome yet (not stored separately); the question
 * follows from the version.
 */
export const contentReports = pgTable(
  'content_reports',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id').references(() => users.id, {
      onDelete: 'set null',
    }),
    questionVersionId: uuid('question_version_id')
      .notNull()
      .references(() => questionVersions.id),
    reason: reportReason('reason').notNull(),
    comment: text('comment'),
    createdAt: createdAt(),
    outcome: reportOutcome('outcome'),
    resolvedBy: uuid('resolved_by').references(() => users.id),
    resolvedAt: timestamp('resolved_at', { withTimezone: true }),
    resolutionNote: text('resolution_note'),
  },
  (t) => [
    index('content_reports_open_idx').on(t.outcome, t.createdAt),
    index('content_reports_version_idx').on(t.questionVersionId),
    // One open report per learner per question version.
    uniqueIndex('content_reports_open_per_user_idx')
      .on(t.userId, t.questionVersionId)
      .where(sql`${t.outcome} is null`),
    // Closed reports say how, by whom and when; open ones say none of it.
    check(
      'content_reports_resolution_check',
      sql`(${t.outcome} is null) = (${t.resolvedAt} is null) and (${t.outcome} is null) = (${t.resolvedBy} is null)`,
    ),
  ],
);

// ---------------------------------------------------------------- imports

export const IMPORT_FORMATS = ['csv', 'xlsx'] as const;
export const importFormat = pgEnum('import_format', IMPORT_FORMATS);

/**
 * What happened to one row: a new draft, an existing question, nothing, or
 * (exam import only) a question the exam body withdrew: no question is made,
 * and the row becomes a withdrawn paper position when the paper is built.
 */
export const IMPORT_OUTCOMES = [
  'created',
  'skipped',
  'failed',
  'withdrawn',
] as const;
export type ImportOutcome = (typeof IMPORT_OUTCOMES)[number];
export const importOutcome = pgEnum('import_outcome', IMPORT_OUTCOMES);

export const PROBLEM_LEVELS = ['error', 'warning'] as const;
export type ProblemLevel = (typeof PROBLEM_LEVELS)[number];
export const problemLevel = pgEnum('problem_level', PROBLEM_LEVELS);

/**
 * A file of questions imported as drafts. Test runs are not stored. The same
 * file (by content) can be imported only once. Counts follow from the rows.
 */
export const importJobs = pgTable('import_jobs', {
  id: uuid('id').primaryKey(),
  createdBy: uuid('created_by')
    .notNull()
    .references(() => users.id),
  fileName: text('file_name').notNull(),
  fileSha256: text('file_sha256').notNull().unique(),
  format: importFormat('format').notNull(),
  /** Where the file's content came from, if it is not written in-house. */
  contentSourceId: uuid('content_source_id').references(
    () => contentSources.id,
  ),
  createdAt: createdAt(),
});

/** One data row of an imported file, by its line in the file (header = 1). */
export const importJobRows = pgTable(
  'import_job_rows',
  {
    jobId: uuid('job_id')
      .notNull()
      .references(() => importJobs.id, { onDelete: 'cascade' }),
    line: integer('line').notNull(),
    externalRef: text('external_ref'),
    outcome: importOutcome('outcome').notNull(),
    /** The draft it created, or the existing question it duplicates. */
    questionId: uuid('question_id').references(() => questions.id),
  },
  (t) => [
    primaryKey({ columns: [t.jobId, t.line] }),
    index('import_job_rows_question_idx').on(t.questionId),
    check(
      'import_job_rows_question_check',
      sql`(${t.outcome} <> 'created' or ${t.questionId} is not null) and (${t.outcome} <> 'failed' or ${t.questionId} is null)`,
    ),
  ],
);

/** Errors (row not imported) and warnings (imported, but not ready for review). */
export const importRowProblems = pgTable(
  'import_row_problems',
  {
    jobId: uuid('job_id').notNull(),
    line: integer('line').notNull(),
    position: smallint('position').notNull(),
    level: problemLevel('level').notNull(),
    field: text('field'),
    reason: text('reason').notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.jobId, t.line, t.position] }),
    foreignKey({
      columns: [t.jobId, t.line],
      foreignColumns: [importJobRows.jobId, importJobRows.line],
    }).onDelete('cascade'),
  ],
);

// ---------------------------------------------------------------- analytics

/**
 * One row per learner per India date they opened the app: the only usage the
 * server does not already know from quizzes and chat, needed for retention.
 * No device ids or screens. Removed with the account.
 */
export const appOpens = pgTable(
  'app_opens',
  {
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    day: date('day').notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.userId, t.day] }),
    index('app_opens_day_idx').on(t.day),
  ],
);

// ---------------------------------------------------------------- mock exams

/** A formal exam that learners can practise: AIBE first, then CLAT and AILET. */
export const exams = pgTable('exams', {
  id: uuid('id').primaryKey(),
  slug: text('slug').notNull().unique(),
  name: text('name').notNull(),
  shortName: text('short_name').notNull(),
  isActive: boolean('is_active').notNull().default(false),
  sortOrder: integer('sort_order').notNull().default(0),
  instructions: text('instructions').notNull().default(''),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const BLUEPRINT_STATUSES = ['draft', 'published', 'retired'] as const;
export type BlueprintStatus = (typeof BLUEPRINT_STATUSES)[number];
export const blueprintStatus = pgEnum('blueprint_status', BLUEPRINT_STATUSES);

/**
 * How sure we are that a blueprint matches the exam's real rules. Timed
 * mode needs official_confirmed; an inferred or unverified blueprint is
 * practice-only until a person approves it.
 */
export const CONFIG_STATUSES = [
  'official_confirmed',
  'inferred',
  'unverified',
] as const;
export type ConfigStatus = (typeof CONFIG_STATUSES)[number];
export const configStatus = pgEnum('config_status', CONFIG_STATUSES);

export const SECTION_NAVIGATIONS = ['free', 'locked_order'] as const;
export const sectionNavigation = pgEnum(
  'section_navigation',
  SECTION_NAVIGATIONS,
);

/**
 * How a randomised mock treats questions about the old codes (IPC, CrPC,
 * Evidence Act). A random mock tests current law, so it leaves old-code-only
 * questions out under every value except include_all. any (the default),
 * exclude_old and prefer_new all leave them out; prefer_new is not a
 * permission to include them. Fixed historical papers are not filtered: they
 * keep their original questions.
 */
export const LAW_REGIME_FILTERS = [
  'any',
  'exclude_old',
  'prefer_new',
  'include_all',
] as const;
export type LawRegimeFilter = (typeof LAW_REGIME_FILTERS)[number];
export const lawRegimeFilter = pgEnum('law_regime_filter', LAW_REGIME_FILTERS);

/** How a question with more than one accepted answer is scored. */
export const ALTERNATE_ANSWER_POLICIES = ['any_accepted'] as const;
export const alternateAnswerPolicy = pgEnum(
  'alternate_answer_policy',
  ALTERNATE_ANSWER_POLICIES,
);

/**
 * The rules of one exam paper format: length, timer and marking. A published
 * blueprint never changes; a change is a new version. Each fixed paper points
 * to its own blueprint, so different years can differ.
 */
export const examBlueprints = pgTable(
  'exam_blueprints',
  {
    id: uuid('id').primaryKey(),
    examId: uuid('exam_id')
      .notNull()
      .references(() => exams.id),
    code: text('code').notNull(),
    version: integer('version').notNull().default(1),
    status: blueprintStatus('status').notNull().default('draft'),
    /**
     * The one blueprint randomised mocks of this exam use. At most one per
     * exam, and only a published one; it is set and cleared on purpose, never
     * as a side effect of publishing.
     */
    isCurrent: boolean('is_current').notNull().default(false),
    durationSeconds: integer('duration_seconds').notNull(),
    totalQuestions: integer('total_questions').notNull(),
    marksCorrect: numeric('marks_correct', {
      precision: 5,
      scale: 2,
    }).notNull(),
    /** Marks taken off for a wrong answer, as a positive number; 0 means none. */
    negativeMarks: numeric('negative_marks', { precision: 5, scale: 2 })
      .notNull()
      .default('0'),
    marksUnanswered: numeric('marks_unanswered', { precision: 5, scale: 2 })
      .notNull()
      .default('0'),
    passPercentGeneral: numeric('pass_percent_general', {
      precision: 5,
      scale: 2,
    }),
    passPercentReserved: numeric('pass_percent_reserved', {
      precision: 5,
      scale: 2,
    }),
    sectionNavigation: sectionNavigation('section_navigation')
      .notNull()
      .default('free'),
    lawRegimeFilter: lawRegimeFilter('law_regime_filter')
      .notNull()
      .default('any'),
    alternateAnswerPolicy: alternateAnswerPolicy('alternate_answer_policy')
      .notNull()
      .default('any_accepted'),
    configStatus: configStatus('config_status').notNull().default('unverified'),
    /** Which document the rules come from, e.g. a BCI notice or booklet. */
    configSource: text('config_source'),
    configCheckedOn: date('config_checked_on'),
    createdBy: uuid('created_by').references(() => users.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex('exam_blueprints_code_version_idx').on(
      t.examId,
      t.code,
      t.version,
    ),
    index('exam_blueprints_exam_idx').on(t.examId, t.status),
    uniqueIndex('exam_blueprints_current_idx')
      .on(t.examId)
      .where(sql`${t.isCurrent}`),
    check(
      'exam_blueprints_current_published_check',
      sql`not ${t.isCurrent} or ${t.status} = 'published'`,
    ),
    check('exam_blueprints_duration_check', sql`${t.durationSeconds} > 0`),
    check('exam_blueprints_total_check', sql`${t.totalQuestions} > 0`),
    check(
      'exam_blueprints_marks_check',
      sql`${t.marksCorrect} >= 0 and ${t.negativeMarks} >= 0 and ${t.marksUnanswered} >= 0`,
    ),
    check(
      'exam_blueprints_pass_check',
      sql`(${t.passPercentGeneral} is null or ${t.passPercentGeneral} between 0 and 100)
        and (${t.passPercentReserved} is null or ${t.passPercentReserved} between 0 and 100)`,
    ),
  ],
);

/** One part of a blueprint (for AIBE, a group of the BCI syllabus). */
export const examSections = pgTable(
  'exam_sections',
  {
    id: uuid('id').primaryKey(),
    blueprintId: uuid('blueprint_id')
      .notNull()
      .references(() => examBlueprints.id),
    code: text('code').notNull(),
    name: text('name').notNull(),
    position: integer('position').notNull(),
    questionCount: integer('question_count').notNull(),
    /** Set only when a section has its own timer. */
    durationSeconds: integer('duration_seconds'),
    /** Set only when a section is marked differently from the blueprint. */
    marksCorrect: numeric('marks_correct', { precision: 5, scale: 2 }),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('exam_sections_code_idx').on(t.blueprintId, t.code),
    uniqueIndex('exam_sections_position_idx').on(t.blueprintId, t.position),
    check('exam_sections_count_check', sql`${t.questionCount} > 0`),
    check(
      'exam_sections_duration_check',
      sql`${t.durationSeconds} is null or ${t.durationSeconds} > 0`,
    ),
  ],
);

/** Which topics a section draws from, and how many questions each may supply. */
export const examSectionTopics = pgTable(
  'exam_section_topics',
  {
    sectionId: uuid('section_id')
      .notNull()
      .references(() => examSections.id),
    topicId: uuid('topic_id')
      .notNull()
      .references(() => topics.id),
    minCount: integer('min_count').notNull().default(0),
    maxCount: integer('max_count'),
    weight: integer('weight').notNull().default(1),
  },
  (t) => [
    primaryKey({ columns: [t.sectionId, t.topicId] }),
    index('exam_section_topics_topic_idx').on(t.topicId),
    check(
      'exam_section_topics_range_check',
      sql`${t.minCount} >= 0 and (${t.maxCount} is null or ${t.maxCount} >= ${t.minCount}) and ${t.weight} > 0`,
    ),
  ],
);

/**
 * Marks a question as usable in an exam's mocks. Every exam-only question
 * needs at least one; an ordinary question is shared by tagging it.
 */
export const examQuestionTags = pgTable(
  'exam_question_tags',
  {
    questionId: uuid('question_id')
      .notNull()
      .references(() => questions.id),
    examId: uuid('exam_id')
      .notNull()
      .references(() => exams.id),
    createdBy: uuid('created_by').references(() => users.id),
    createdAt: createdAt(),
  },
  (t) => [
    primaryKey({ columns: [t.questionId, t.examId] }),
    index('exam_question_tags_exam_idx').on(t.examId),
  ],
);

// ---------------------------------------------------------------- fixed exam papers

/** A paper is edited as a draft; publishing freezes it, and a change is a new revision. */
export const PAPER_STATUSES = ['draft', 'published', 'retired'] as const;
export type PaperStatus = (typeof PAPER_STATUSES)[number];
export const paperStatus = pgEnum('paper_status', PAPER_STATUSES);

/**
 * How a position scores when the exam body withdrew its question. Until the
 * rule for a paper is confirmed it is unscored: the position is left out of
 * the marks and the percentage.
 */
export const WITHDRAWN_POLICIES = ['unscored', 'award_all'] as const;
export type WithdrawnPolicy = (typeof WITHDRAWN_POLICIES)[number];
export const withdrawnPolicy = pgEnum('withdrawn_policy', WITHDRAWN_POLICIES);

export const PAPER_ANSWER_STATUSES = [
  'keyed',
  'multi_accepted',
  'withdrawn',
] as const;
export type PaperAnswerStatus = (typeof PAPER_ANSWER_STATUSES)[number];
export const paperAnswerStatus = pgEnum(
  'paper_answer_status',
  PAPER_ANSWER_STATUSES,
);

export const KEY_HISTORY_KINDS = [
  'provisional',
  'final',
  'revised',
  'withdrawn',
] as const;
export type KeyHistoryKind = (typeof KEY_HISTORY_KINDS)[number];
export const keyHistoryKind = pgEnum('key_history_kind', KEY_HISTORY_KINDS);

/**
 * One previous-year paper (or one set of it), as it was set. Revision 1 is
 * the first record; a later correction is a new row pointing back to the one
 * it replaces. Once published a paper is frozen: the service refuses any
 * change to it or its positions.
 */
export const examPapers = pgTable(
  'exam_papers',
  {
    id: uuid('id').primaryKey(),
    examId: uuid('exam_id')
      .notNull()
      .references(() => exams.id),
    /** Stable across revisions, e.g. aibe-xviii-set-a. */
    code: text('code').notNull(),
    revision: integer('revision').notNull().default(1),
    supersedesId: uuid('supersedes_id').references(
      (): AnyPgColumn => examPapers.id,
    ),
    title: text('title').notNull(),
    /** The edition as the body names it, e.g. XVIII. */
    edition: text('edition'),
    year: integer('year'),
    /** The booklet set, e.g. A. */
    setLabel: text('set_label'),
    status: paperStatus('status').notNull().default('draft'),
    frozenAt: timestamp('frozen_at', { withTimezone: true }),
    /** The blueprint whose rules this paper follows, when one applies. */
    blueprintId: uuid('blueprint_id').references(() => examBlueprints.id),
    totalQuestions: integer('total_questions').notNull(),
    durationSeconds: integer('duration_seconds'),
    /**
     * An admin-set clock for practising against this paper. It is not the
     * official exam time and never makes the paper's rules "confirmed": the
     * official timed mode still needs duration_seconds and official_confirmed.
     */
    practiceTimerSeconds: integer('practice_timer_seconds'),
    marksCorrect: numeric('marks_correct', { precision: 5, scale: 2 }),
    negativeMarks: numeric('negative_marks', { precision: 5, scale: 2 }),
    marksUnanswered: numeric('marks_unanswered', { precision: 5, scale: 2 }),
    withdrawnPolicy: withdrawnPolicy('withdrawn_policy')
      .notNull()
      .default('unscored'),
    /** A person has confirmed the withdrawn rule from the exam body's notice. */
    withdrawnPolicyConfirmed: boolean('withdrawn_policy_confirmed')
      .notNull()
      .default(false),
    configStatus: configStatus('config_status').notNull().default('unverified'),
    sourceNote: text('source_note'),
    createdBy: uuid('created_by').references(() => users.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex('exam_papers_code_revision_idx').on(
      t.examId,
      t.code,
      t.revision,
    ),
    uniqueIndex('exam_papers_published_idx')
      .on(t.examId, t.code)
      .where(sql`${t.status} = 'published'`),
    index('exam_papers_exam_idx').on(t.examId, t.status),
    check('exam_papers_total_check', sql`${t.totalQuestions} > 0`),
    check(
      'exam_papers_marks_check',
      sql`(${t.marksCorrect} is null or ${t.marksCorrect} >= 0)
        and (${t.negativeMarks} is null or ${t.negativeMarks} >= 0)
        and (${t.marksUnanswered} is null or ${t.marksUnanswered} >= 0)`,
    ),
    check(
      'exam_papers_duration_check',
      sql`${t.durationSeconds} is null or ${t.durationSeconds} > 0`,
    ),
    check(
      'exam_papers_frozen_check',
      sql`(${t.status} = 'draft') = (${t.frozenAt} is null)`,
    ),
    check(
      'exam_papers_award_all_check',
      sql`${t.withdrawnPolicy} <> 'award_all' or ${t.withdrawnPolicyConfirmed}`,
    ),
  ],
);

/**
 * One position of a paper. It pins an exact, immutable question version, or
 * is a placeholder for a question the body withdrew (no version).
 */
export const examPaperQuestions = pgTable(
  'exam_paper_questions',
  {
    id: uuid('id').primaryKey(),
    paperId: uuid('paper_id')
      .notNull()
      .references(() => examPapers.id),
    position: integer('position').notNull(),
    questionId: uuid('question_id').references(() => questions.id),
    questionVersionId: uuid('question_version_id').references(
      () => questionVersions.id,
    ),
    answerStatus: paperAnswerStatus('answer_status').notNull(),
    /** The number the question carried in the original paper. */
    originalRef: text('original_ref'),
    /** Option ids in the order shown; null means the version's own order. */
    optionOrder: jsonb('option_order').$type<string[]>(),
    /** How the original labelled options, e.g. "A-D" or "1-4". */
    originalLabelScheme: text('original_label_scheme'),
    /** Where this position's key was taken from, in the body's words. */
    officialKeyText: text('official_key_text'),
    sourceRef: text('source_ref'),
    withdrawnNote: text('withdrawn_note'),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('exam_paper_questions_position_idx').on(t.paperId, t.position),
    index('exam_paper_questions_version_idx').on(t.questionVersionId),
    check('exam_paper_questions_position_check', sql`${t.position} >= 1`),
    check(
      'exam_paper_questions_withdrawn_check',
      sql`(${t.answerStatus} = 'withdrawn') = (${t.questionVersionId} is null)
        and (${t.questionVersionId} is null) = (${t.questionId} is null)`,
    ),
  ],
);

/**
 * Append-only record of what the official key said for a position, and where
 * that came from. The newest row is the effective key; a position without
 * rows uses the pinned version's own key.
 */
export const examPaperKeyHistory = pgTable(
  'exam_paper_key_history',
  {
    id: uuid('id').primaryKey(),
    paperId: uuid('paper_id')
      .notNull()
      .references(() => examPapers.id),
    paperQuestionId: uuid('paper_question_id')
      .notNull()
      .references(() => examPaperQuestions.id),
    kind: keyHistoryKind('kind').notNull(),
    /** Every option the body accepted; empty for a withdrawn question. */
    acceptedOptionIds: jsonb('accepted_option_ids')
      .$type<string[]>()
      .notNull()
      .default([]),
    contentSourceId: uuid('content_source_id').references(
      () => contentSources.id,
    ),
    /** The document, in words: title, notice number, page. */
    sourceDocumentRef: text('source_document_ref'),
    retrievedOn: date('retrieved_on'),
    sourceSha256: text('source_sha256'),
    note: text('note'),
    recordedBy: uuid('recorded_by').references(() => users.id),
    createdAt: createdAt(),
  },
  (t) => [
    index('exam_paper_key_history_pq_idx').on(t.paperQuestionId, t.createdAt),
    index('exam_paper_key_history_paper_idx').on(t.paperId),
    check(
      'exam_paper_key_history_sha_check',
      sql`${t.sourceSha256} is null or ${t.sourceSha256} ~ '^[0-9a-f]{64}$'`,
    ),
  ],
);

// ---------------------------------------------------------------- formal exam attempts

export const EXAM_ATTEMPT_KINDS = ['fixed_paper', 'random_mock'] as const;
export type ExamAttemptKind = (typeof EXAM_ATTEMPT_KINDS)[number];
export const examAttemptKind = pgEnum('exam_attempt_kind', EXAM_ATTEMPT_KINDS);

/** Practice has no deadline; timed has one the server sets and enforces. */
export const EXAM_ATTEMPT_MODES = ['practice', 'timed'] as const;
export type ExamAttemptMode = (typeof EXAM_ATTEMPT_MODES)[number];
export const examAttemptMode = pgEnum('exam_attempt_mode', EXAM_ATTEMPT_MODES);

export const EXAM_ATTEMPT_STATUSES = [
  'in_progress',
  'submitted',
  'expired',
] as const;
export type ExamAttemptStatus = (typeof EXAM_ATTEMPT_STATUSES)[number];
export const examAttemptStatus = pgEnum(
  'exam_attempt_status',
  EXAM_ATTEMPT_STATUSES,
);

/**
 * One formal exam attempt. Separate from the learning games (quiz_sessions):
 * it earns no XP, coins, energy, streak or league points. Everything that
 * scores it is copied here when it starts, so later changes to the paper,
 * blueprint or questions never alter an attempt that exists.
 */
export const examAttempts = pgTable(
  'exam_attempts',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id),
    examId: uuid('exam_id')
      .notNull()
      .references(() => exams.id),
    kind: examAttemptKind('kind').notNull(),
    mode: examAttemptMode('mode').notNull(),
    status: examAttemptStatus('status').notNull().default('in_progress'),
    paperId: uuid('paper_id').references(() => examPapers.id),
    paperRevision: integer('paper_revision'),
    blueprintId: uuid('blueprint_id').references(() => examBlueprints.id),
    language: text('language').notNull().default('en'),
    /** Random mocks: the seed and algorithm version that built the question list. */
    seed: text('seed'),
    algorithmVersion: integer('algorithm_version'),
    startedAt: timestamp('started_at', { withTimezone: true })
      .notNull()
      .defaultNow(),
    /** Set by the server at start (timed only); the client only displays it. */
    deadlineAt: timestamp('deadline_at', { withTimezone: true }),
    durationSeconds: integer('duration_seconds'),
    submittedAt: timestamp('submitted_at', { withTimezone: true }),
    /** learner, expiry (lazily, when touched after the deadline) or sweep. */
    finalisedBy: text('finalised_by'),
    /** Locked-order blueprints only: the section answers may be saved to. */
    currentSectionPosition: integer('current_section_position'),
    sectionNavigation: sectionNavigation('section_navigation')
      .notNull()
      .default('free'),
    // The marking rules in force, copied at start. Null means not configured.
    marksCorrect: numeric('marks_correct', { precision: 5, scale: 2 }),
    negativeMarks: numeric('negative_marks', { precision: 5, scale: 2 }),
    marksUnanswered: numeric('marks_unanswered', { precision: 5, scale: 2 }),
    withdrawnPolicy: withdrawnPolicy('withdrawn_policy')
      .notNull()
      .default('unscored'),
    withdrawnPolicyConfirmed: boolean('withdrawn_policy_confirmed')
      .notNull()
      .default(false),
    /** The rules came from a source marked official_confirmed. */
    rulesVerified: boolean('rules_verified').notNull().default(false),
    passPercentGeneral: numeric('pass_percent_general', {
      precision: 5,
      scale: 2,
    }),
    passPercentReserved: numeric('pass_percent_reserved', {
      precision: 5,
      scale: 2,
    }),
    /** Written once, when the attempt is finalised. */
    result: jsonb('result').$type<Record<string, unknown>>(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    // At most one open attempt per learner and exam; also makes a double
    // "start" request safe.
    uniqueIndex('exam_attempts_open_idx')
      .on(t.userId, t.examId)
      .where(sql`${t.status} = 'in_progress'`),
    index('exam_attempts_user_idx').on(t.userId, t.id),
    index('exam_attempts_deadline_idx')
      .on(t.deadlineAt)
      .where(sql`${t.status} = 'in_progress'`),
    // An official timed attempt always has a deadline. A practice attempt may
    // also have one (the paper's practice timer).
    check(
      'exam_attempts_deadline_check',
      sql`${t.mode} <> 'timed' or ${t.deadlineAt} is not null`,
    ),
    check(
      'exam_attempts_closed_check',
      sql`(${t.status} = 'in_progress') = (${t.submittedAt} is null)`,
    ),
    check(
      'exam_attempts_paper_check',
      sql`(${t.kind} = 'fixed_paper') = (${t.paperId} is not null)`,
    ),
  ],
);

/** The frozen content of one position of an attempt, and the learner's answer to it. */
export const examAttemptQuestions = pgTable(
  'exam_attempt_questions',
  {
    id: uuid('id').primaryKey(),
    attemptId: uuid('attempt_id')
      .notNull()
      .references(() => examAttempts.id),
    position: integer('position').notNull(),
    sectionCode: text('section_code'),
    sectionPosition: integer('section_position'),
    questionId: uuid('question_id').references(() => questions.id),
    questionVersionId: uuid('question_version_id').references(
      () => questionVersions.id,
    ),
    topicId: uuid('topic_id'),
    answerStatus: paperAnswerStatus('answer_status').notNull(),
    questionType: text('question_type').notNull().default('single_select'),
    /** Option ids in the order shown to this learner. */
    optionOrder: jsonb('option_order').$type<string[]>(),
    originalRef: text('original_ref'),
    originalLabelScheme: text('original_label_scheme'),
    /** The key as it stood at start. Never sent to the learner before submission. */
    acceptedOptionIds: jsonb('accepted_option_ids')
      .$type<string[]>()
      .notNull()
      .default([]),
    /** Marks for a correct answer here; null when not configured. */
    marksCorrect: numeric('marks_correct', { precision: 5, scale: 2 }),
    selectedOptionIds: jsonb('selected_option_ids').$type<string[]>(),
    /** The client's counter for this answer; an older one never overwrites a newer one. */
    answerSeq: integer('answer_seq').notNull().default(0),
    answeredAt: timestamp('answered_at', { withTimezone: true }),
  },
  (t) => [
    uniqueIndex('exam_attempt_questions_position_idx').on(
      t.attemptId,
      t.position,
    ),
    index('exam_attempt_questions_question_idx').on(t.questionId),
    check('exam_attempt_questions_position_check', sql`${t.position} >= 1`),
    check(
      'exam_attempt_questions_withdrawn_check',
      sql`(${t.answerStatus} = 'withdrawn') = (${t.questionVersionId} is null)`,
    ),
    check('exam_attempt_questions_seq_check', sql`${t.answerSeq} >= 0`),
  ],
);
